+// API keys, roles and the audit log. A key has a `name` and a `role`:
+// viewer reads; cook also cooks, wastes, logs temperatures and enters
+// stock-take counts; manager may do everything. Audit entries are appended,
+// never edited or deleted.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles, from fewest to most rights. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+// The roles allowed for each permission a route may require.
+const GRANTS = {
+  read: ["viewer", "cook", "manager"],
+  cook: ["cook", "manager"],
+  manage: ["manager"],
+};
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for a presented key, or null. */
+export function findKey(store, presented) {
+  if (typeof presented !== "string" || presented === "") return null;
+  const want = digest(presented);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key !== "string" || k.key === "") continue;
+    if (timingSafeEqual(digest(k.key), want) && !found) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` holds `permission` ("read", "cook" or "manage"). */
+export function allows(role, permission) {
+  return (GRANTS[permission] ?? []).includes(role);
+}
+
+/** Appends an audit entry { at, key, method, path, status }; returns it. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
